#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static int expected(const vector<int>& price, int x) {
    int cnt = 0;
    for (size_t i = 0; i < price.size(); ++i)
        if (x >= price[i]) { x -= price[i]; ++cnt; }
    return cnt;
}

static bool check(const string& exe, const vector<int>& price, int x, int id) {
    const string inFile = "l3as1_input.txt", outFile = "l3as1_output.txt";
    {
        ofstream out(inFile);
        out << price.size() << '\n';
        for (size_t i = 0; i < price.size(); ++i) out << price[i] << (i+1 == price.size() ? '\n' : ' ');
        out << x << '\n';
    }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string output((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    istringstream parser(output);
    int actual = -1;
    string extra;
    const int want = expected(price, x);
    bool ok = code == 0 && (parser >> actual) && !(parser >> extra) && actual == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": n=" << price.size() << ", x=" << x
             << ", expected=" << want << ", actual=" << output.substr(0, 120)
             << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    struct Case { vector<int> price; int x; };
    vector<Case> tests = {
        {{7, 5, 9, 10, 7, 4}, 30},  // PDF 样例 -> 4
        {{5}, 5}, {{6}, 5}, {{1, 2, 3}, 0}, {{1, 2, 3, 4}, 10},
        {{5, 6, 7}, 4}, {{10, 1, 1, 1, 1}, 10}, {{100, 100, 100}, 300}
    };
    unsigned seed = 20261114u;
    for (int trial = 0; trial < 8; ++trial) {
        int n = trial == 7 ? 100 : 2 + trial * 13;
        vector<int> price;
        for (int i = 0; i < n; ++i) {
            seed = seed * 1664525u + 1013904223u;
            price.push_back(1 + static_cast<int>(seed % 1000u));
        }
        seed = seed * 1664525u + 1013904223u;
        tests.push_back(Case{price, static_cast<int>(seed % 5000u)});
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i].price, tests[i].x, static_cast<int>(i+1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}

