    if (d < 10)
        return (char)(d + '0');
    return (char)(d + 'A' - 10);
}
int main() {
    int n = 0, r = 0;
    cin >> n >> r;
    while (n > 0) {
        res[len] = trans(n % r);
        n /= r;
        len++;
    }
    for (int i = len - 1; i >= 0; i--)
        cout << res[i];
    cout << endl;
    return 0;
}

