#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
#include <utility>
#include <vector>
using namespace std;

static string expected(long long n, int r) {
    const char* D = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (n == 0) return "0";
    string s;
    while (n > 0) { s = string(1, D[n % r]) + s; n /= r; }
    return s;
}

static string trim(const string& s) {
    size_t b = s.find_first_not_of(" \t\r\n");
    if (b == string::npos) return "";
    size_t e = s.find_last_not_of(" \t\r\n");
    return s.substr(b, e - b + 1);
}

static bool check(const string& exe, long long n, int r, int id) {
    const string inFile = "l3as2_input.txt", outFile = "l3as2_output.txt";
    { ofstream out(inFile); out << n << '\n' << r << '\n'; }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    string output((istreambuf_iterator<char>(in)), istreambuf_iterator<char>());
    const string want = expected(n, r);
    bool ok = code == 0 && trim(output) == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": n=" << n << ", r=" << r
             << ", expected=" << want << ", actual=" << trim(output).substr(0, 120)
             << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<pair<long long,int>> tests = {
        {123, 25},   // PDF 样例 -> 4N
        {1, 2}, {1000000, 36}, {255, 16}, {10, 2}, {35, 36},
        {36, 36}, {999999, 2}, {1000000, 2}, {7, 8}
    };
    unsigned seed = 20261114u;
    for (int trial = 0; trial < 8; ++trial) {
        seed = seed * 1664525u + 1013904223u;
        long long n = 1 + seed % 1000000u;
        seed = seed * 1664525u + 1013904223u;
        int r = 2 + static_cast<int>(seed % 35u);
        tests.push_back(make_pair(n, r));
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i].first, tests[i].second, static_cast<int>(i+1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}
